$ cat Hot2.java
public class Hot2 {
    static int add(int a, int b) { return a + b; }
    public static void main(String[] x) {
        int n = Integer.parseInt(x[0]);
        long t0 = System.nanoTime(), s = 0;
        for (int i = 0; i < n; i++) s += add(i, 1);
        System.out.printf("%,d ms (s=%d)%n", (System.nanoTime()-t0)/1_000_000, s);
    }
}

$ for N in 1000 100000 10000000 300000000; do
    for OPT in -Xint "" -Xcomp; do java $OPT -cp out Hot2 $N; done
  done

  반복             -Xint        기본         -Xcomp
  1000             0 ms         0 ms         0 ms
  100000           3 ms         1 ms         1 ms
  10000000       349 ms         9 ms        29 ms
  300000000    7,640 ms       217 ms       759 ms

# --- -Xcomp 를 두 번 더 ---

  기본     273 ms      -Xcomp  814 ms
  기본     218 ms      -Xcomp  935 ms

# 3억 회에서 -Xint 는 기본의 35배, -Xcomp 는 3.5배 느리다.
